import React from "react";
import AddOrganisation from "./components/addOrganisation";
import AddChecker from "./components/addChecker";
import RoleSelection from "./components/roleSelection";
import AuthUser from "./components/auth";
import Verification from './components/verifyAccount';
import VerificationOrg from "./components/verifyAccountOrg";

class Registration extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      role: "",
      isRegistering: false,
      isCheckerCompleted: false,
      isOrgCompleted: false
    };
  }

  render() {
    return (
      <div className="container">
        {!this.state.isRegistering && this.state.role === "" && <AuthUser onRegister={this.handleRegister} />}
        {this.state.isRegistering && <RoleSelection onAdd={this.addUser} />}
        {this.state.role === "Organisation" && !this.state.isCheckerCompleted && <AddOrganisation onComplete={this.handleCheckerCompletion}/>} 
        {this.state.role === "Checker" && !this.state.isCheckerCompleted && <AddChecker onComplete={this.handleCheckerCompletion} />}
        {this.state.isCheckerCompleted && <Verification />} 
        {this.state.isOrgCompleted && <Verification />} 
      </div>
    );
  }

  addUser = (user) => {
    this.setState({ role: user.role, isRegistering: false });
    console.log(user);
  }

  handleRegister = () => {
    this.setState({ isRegistering: true });
  }

  handleCheckerCompletion = () => {
    this.setState({ isCheckerCompleted: true });
  }

  handleCheckerCompletion = () => {
    this.setState({ isCheckerCompleted: true });
  }
}

export default Registration;
